import { defineConfig, mergeConfig } from 'vitest/config';

import { vitestCommonConfig } from '../../vitest.shared';

export default mergeConfig(
  vitestCommonConfig,
  defineConfig({
    // Add custom config here
  })
);

export const getVersionSpecifier = (addon: string) => {
  const groups = /^(@{0,1}[^@]+)(?:@(.+))?$/.exec(addon);
  if (groups) {
    return [groups[1], groups[2]] as const;
  }
  return [addon, undefined] as const;
};

const checkInstalled = (addonName: string, main: StorybookConfigRaw) => {
  const existingAddon = main.addons?.find((entry: string | { name: string }) => {
    const name = typeof entry === 'string' ? entry : entry.name;
    return name?.endsWith(addonName);
  });
  return !!existingAddon;
};

function isValidVersion(version: string) {
  return SemVer.valid(version) || version.match(/^\d+$/);
}

export async function migrate(migration: any, { glob, dryRun, list, rename, parser }: CLIOptions) {
  if (list) {
    listCodemods().forEach((key: any) => logger.log(key));
  } else if (migration) {
    await runCodemod(migration, { glob, dryRun, logger, rename, parser });
  } else {
    throw new Error('Migrate: please specify a migration name or --list');
  }
}

async function promptSelectedTemplate(choices: Choice[]): Promise<Choice | null> {
  // using any here as the types are too strict
  const selected = await prompt.select<any>({
    message: 'Select a template',
    options: choices.map(toChoices),
  });
  return selected as Choice;
}

export interface PostinstallOptions {
  packageManager: PackageManagerName;
  configDir: string;
  logger: typeof nodeLogger;
  prompt: typeof prompt;
  yes?: boolean;
  skipInstall?: boolean;
  /**
   * Skip all dependency management (collecting, adding to package.json, installing). Used when the
   * caller (e.g., init command) has already handled dependencies.
   */
  skipDependencyManagement?: boolean;
}

